// Leaderboards (GDD section 6, Leaderboards): total level, each of the
// sixteen skills, net worth, and guilds. There is no story board: the GDD
// rules one out so reading never turns into a race. Boards are read from the
// projections (skills, purse, inventory, open orders), so a Tinker counts as
// of the last time it was touched. The GDD keeps leaderboards in Valkey
// (section 11); until then Postgres answers, as it does for everything else.
// A fully banned account's Tinkers are never shown, nor counted in a guild.

import * as rules from "@long-boil/rules";
import type { GameContent } from "./content-loader.js";
import type { Db } from "./db.js";
import { NotFound } from "./settle.js";
import { BadRequest } from "./tinkers.js";

/** How many rows a board shows; the caller's own row comes too when it is lower. */
export const BOARD_SIZE = 100;

/** Every board: total level, net worth, guilds, then each of the GDD's sixteen skills. */
export const BOARDS = ["total", "net_worth", "guilds", ...rules.GDD_SKILLS] as const;
export type Board = (typeof BOARDS)[number];

export interface BoardRow {
  rank: number;
  /** A Tinker's id, or a guild's on the guild board. */
  id: number;
  name: string;
  /** Total level, a skill's level, Crowns of net worth, or a guild's members' total levels. */
  value: number;
  /** XP on the level boards, members on the guild board, nothing on net worth. */
  detail: number | null;
  /** The caller's Tinker, or the caller's guild. */
  you: boolean;
}

export interface LeaderboardView {
  board: Board;
  boards: Board[];
  size: number;
  rows: BoardRow[];
  /** The caller's row wherever it falls, or null when it is not on this board. */
  you: BoardRow | null;
}

interface Entry {
  id: number;
  name: string;
  value: number;
  /** Breaks a tie in value: total XP on the total board, XP on a skill board. */
  tie: number;
  detail: number | null;
}

/** A Tinker is shown unless its account is fully banned (migration 018). */
const SHOWN = "a.ban IS DISTINCT FROM 'full'";

/** Best first. Equal scores share a rank, and the next rank skips as many as shared it. */
function ranked(entries: Entry[], mine: number | null): BoardRow[] {
  const sorted = [...entries].sort((a, b) => b.value - a.value || b.tie - a.tie || a.name.localeCompare(b.name) || a.id - b.id);
  let place = 0;
  return sorted.map((entry, index) => {
    const before = sorted[index - 1];
    if (!before || before.value !== entry.value || before.tie !== entry.tie) place = index + 1;
    return { rank: place, id: entry.id, name: entry.name, value: entry.value, detail: entry.detail, you: entry.id === mine };
  });
}

async function shownTinkers(db: Db): Promise<Map<number, { name: string; crowns: number }>> {
  const rows = (await db.query(`SELECT t.id, t.name, t.crowns FROM tinkers t JOIN accounts a ON a.id = t.account_id WHERE ${SHOWN}`)).rows;
  return new Map(rows.map((row) => [Number(row.id), { name: row.name as string, crowns: Number(row.crowns) }]));
}

async function shownSkills(db: Db): Promise<Map<number, Record<string, number>>> {
  const rows = (
    await db.query(
      `SELECT s.tinker_id, s.skill, s.xp FROM skills s JOIN tinkers t ON t.id = s.tinker_id JOIN accounts a ON a.id = t.account_id WHERE ${SHOWN}`,
    )
  ).rows;
  const xp = new Map<number, Record<string, number>>();
  for (const row of rows) {
    const id = Number(row.tinker_id);
    if (!xp.has(id)) xp.set(id, {});
    xp.get(id)![row.skill] = Number(row.xp);
  }
  return xp;
}

const sum = (xp: Record<string, number>) => Object.values(xp).reduce((total, amount) => total + amount, 0);

async function totalBoard(db: Db, content: GameContent): Promise<Entry[]> {
  const tinkers = await shownTinkers(db);
  const skills = await shownSkills(db);
  return [...tinkers].map(([id, tinker]) => {
    const xp = skills.get(id) ?? {};
    return { id, name: tinker.name, value: rules.totalLevel(xp, content.rules), tie: sum(xp), detail: sum(xp) };
  });
}

/** Only Tinkers with some XP in the skill; everyone else would tie at level 1. */
async function skillBoard(db: Db, content: GameContent, skill: string): Promise<Entry[]> {
  const rows = (
    await db.query(
      `SELECT t.id, t.name, s.xp FROM skills s JOIN tinkers t ON t.id = s.tinker_id JOIN accounts a ON a.id = t.account_id
       WHERE s.skill = $1 AND s.xp > 0 AND ${SHOWN}`,
      [skill],
    )
  ).rows;
  return rows.map((row) => {
    const xp = Number(row.xp);
    return { id: Number(row.id), name: row.name, value: rules.levelFor(xp, content.rules), tie: xp, detail: xp };
  });
}

/**
 * Net worth: Crowns in the purse and in open buy orders, plus unbound goods,
 * held or offered in open sell orders, at the collectors' price. Goods no
 * collector buys count nothing, and Gilded Cogs are left out, since they are
 * bought with money and nothing may be exclusive to paying players (GDD).
 */
async function netWorthBoard(db: Db, content: GameContent): Promise<Entry[]> {
  const tinkers = await shownTinkers(db);
  const worth = new Map([...tinkers].map(([id, tinker]) => [id, tinker.crowns]));
  const priceOf = (item: string) => content.economy.get(item)?.collectorPrice ?? 0;
  const add = (id: number, crowns: number) => {
    if (worth.has(id)) worth.set(id, worth.get(id)! + crowns);
  };
  for (const row of (await db.query("SELECT tinker_id, item, qty FROM inventory WHERE bound = false")).rows) {
    add(Number(row.tinker_id), priceOf(row.item) * Number(row.qty));
  }
  for (const row of (await db.query("SELECT tinker_id, item, side, price, qty_open FROM exchange_orders WHERE closed_at IS NULL")).rows) {
    const qty = Number(row.qty_open);
    add(Number(row.tinker_id), row.side === "buy" ? Number(row.price) * qty : priceOf(row.item) * qty);
  }
  return [...tinkers].map(([id, tinker]) => ({ id, name: tinker.name, value: worth.get(id)!, tie: 0, detail: null }));
}

/** Formed guilds, by their shown members' total levels added together. */
async function guildBoard(db: Db, content: GameContent): Promise<Entry[]> {
  const skills = await shownSkills(db);
  const rows = (
    await db.query(
      `SELECT g.id, g.name, m.tinker_id FROM guilds g JOIN guild_members m ON m.guild_id = g.id
       JOIN tinkers t ON t.id = m.tinker_id JOIN accounts a ON a.id = t.account_id
       WHERE g.status = 'active' AND ${SHOWN}`,
    )
  ).rows;
  const guilds = new Map<number, Entry>();
  for (const row of rows) {
    const id = Number(row.id);
    const entry = guilds.get(id) ?? { id, name: row.name, value: 0, tie: 0, detail: 0 };
    entry.value += rules.totalLevel(skills.get(Number(row.tinker_id)) ?? {}, content.rules);
    entry.detail = (entry.detail ?? 0) + 1;
    guilds.set(id, entry);
  }
  return [...guilds.values()];
}

/** One board as this Tinker sees it: the top rows, and its own row or its guild's. */
export async function leaderboard(db: Db, content: GameContent, tinkerId: number, board: string): Promise<LeaderboardView> {
  if (!(BOARDS as readonly string[]).includes(board)) throw new BadRequest(`there is no ${board} board`);
  if (!(await db.query("SELECT 1 FROM tinkers WHERE id = $1", [tinkerId])).rowCount) throw new NotFound(`no Tinker ${tinkerId}`);
  let entries: Entry[];
  let mine: number | null = tinkerId;
  if (board === "total") entries = await totalBoard(db, content);
  else if (board === "net_worth") entries = await netWorthBoard(db, content);
  else if (board === "guilds") {
    entries = await guildBoard(db, content);
    const own = (await db.query("SELECT guild_id FROM guild_members WHERE tinker_id = $1", [tinkerId])).rows[0];
    mine = own ? Number(own.guild_id) : null;
  } else entries = await skillBoard(db, content, board);
  const rows = ranked(entries, mine);
  return { board: board as Board, boards: [...BOARDS], size: BOARD_SIZE, rows: rows.slice(0, BOARD_SIZE), you: rows.find((row) => row.you) ?? null };
}

// Leaderboards through the API (GDD section 6, Leaderboards), against a real
// PostgreSQL database, long_boil_test, rebuilt from the migrations.

import { levelFor, totalLevel } from "@long-boil/rules";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { buildApi } from "../src/api.js";
import { loadContent } from "../src/content-loader.js";
import { connect, migrate } from "../src/db.js";

const db = connect(process.env.PGDATABASE_TEST ?? "long_boil_test");
const content = loadContent();
const clock = Date.UTC(2026, 10, 10, 8, 0, 0);
const app = buildApi({ db, content, now: () => clock });

// An item the collectors buy, for valuing goods in net worth.
const [goods, terms] = [...content.economy].find(([, entry]) => entry.collectorPrice !== null)!;
const goodsPrice = terms.collectorPrice!;

let ada: number;
let bram: number;
let cog: number;

async function call(method: "GET" | "POST", url: string, payload?: object) {
  const response = await app.inject({ method, url, ...(payload ? { payload } : {}) });
  return { status: response.statusCode, body: response.json() };
}

/** Test setup: a Tinker with an empty pack, a set purse, and the XP given. */
async function tinker(login: string, name: string, crowns: number, xp: Record<string, number>): Promise<number> {
  const id = (await call("POST", "/tinkers", { login, name })).body.tinker.id;
  await db.query("DELETE FROM inventory WHERE tinker_id = $1", [id]);
  await db.query("UPDATE tinkers SET crowns = $2 WHERE id = $1", [id, crowns]);
  for (const [skill, amount] of Object.entries(xp)) {
    await db.query(
      "INSERT INTO skills (tinker_id, skill, xp) VALUES ($1, $2, $3) ON CONFLICT (tinker_id, skill) DO UPDATE SET xp = EXCLUDED.xp",
      [id, skill, amount],
    );
  }
  return id;
}

async function expectedTotal(id: number): Promise<number> {
  const rows = (await db.query("SELECT skill, xp FROM skills WHERE tinker_id = $1", [id])).rows;
  return totalLevel(Object.fromEntries(rows.map((row) => [row.skill, Number(row.xp)])), content.rules);
}

async function board(id: number, name: string) {
  return (await call("GET", `/tinkers/${id}/leaderboards/${name}`)).body;
}

async function guild(name: string, status: "active" | "charter", members: [number, string][]) {
  const at = new Date(clock);
  const id = (
    await db.query("INSERT INTO guilds (name, status, pledged, created_at, charter_ends, formed_at) VALUES ($1, $2, 500000, $3, $3, $4) RETURNING id", [
      name,
      status,
      at,
      status === "active" ? at : null,
    ])
  ).rows[0].id;
  for (const [tinkerId, rank] of members) {
    await db.query(
      "INSERT INTO guild_members (guild_id, tinker_id, account_id, rank, joined_at) SELECT $1, id, account_id, $3, $4 FROM tinkers WHERE id = $2",
      [id, tinkerId, rank, at],
    );
  }
  return Number(id);
}

beforeAll(async () => {
  await db.query("DROP SCHEMA public CASCADE; CREATE SCHEMA public;");
  await migrate(db);
  ada = await tinker("lb-ada@example.com", "Ada", 1_000, { smithing: 2_000_000, cooking: 5_000 });
  bram = await tinker("lb-bram@example.com", "Bram", 5_000, { smithing: 20_000, cooking: 5_000 });
  cog = await tinker("lb-cog@example.com", "Cog", 200, { cooking: 0 });
});

afterAll(async () => {
  await app.close();
  await db.end();
});

describe("the leaderboards", () => {
  it("ranks total level, best first, and marks your own row", async () => {
    const view = await board(cog, "total");
    expect(view.boards).toEqual(expect.arrayContaining(["total", "net_worth", "guilds", "cooking", "tea_blending", "aetherics"]));
    expect(view.boards).toHaveLength(19);
    expect(view.rows.map((row: { name: string }) => row.name)).toEqual(["Ada", "Bram", "Cog"]);
    expect(view.rows[0]).toMatchObject({ rank: 1, value: await expectedTotal(ada), you: false });
    expect(view.you).toMatchObject({ rank: 3, name: "Cog", value: await expectedTotal(cog), you: true });
  });

  it("ranks a skill by XP, shares a rank on a tie, and leaves out the untrained", async () => {
    const view = await board(ada, "cooking");
    expect(view.rows).toEqual([
      expect.objectContaining({ rank: 1, name: "Ada", value: levelFor(5_000, content.rules), detail: 5_000, you: true }),
      expect.objectContaining({ rank: 1, name: "Bram", detail: 5_000, you: false }),
    ]);
    expect((await board(cog, "cooking")).you).toBeNull();
  });

  it("counts net worth from the purse, open buy orders and goods at the collectors' price", async () => {
    await db.query("INSERT INTO inventory (tinker_id, item, bound, qty) VALUES ($1, $2, false, 3), ($1, $2, true, 2)", [ada, goods]);
    await db.query(
      `INSERT INTO exchange_orders (tinker_id, item, side, price, qty_total, qty_open, placed_at, expires_at)
       VALUES ($1, $2, 'buy', 100, 5, 5, $3, $4)`,
      [cog, goods, new Date(clock), new Date(clock + 30 * 86_400_000)],
    );
    const view = await board(bram, "net_worth");
    const worth = Object.fromEntries(view.rows.map((row: { name: string; value: number }) => [row.name, row.value]));
    expect(worth).toEqual({ Ada: 1_000 + 3 * goodsPrice, Bram: 5_000, Cog: 700 });
    const values = view.rows.map((row: { value: number }) => row.value);
    expect(values).toEqual([...values].sort((a, b) => b - a));
    expect(view.you.name).toBe("Bram");
  });

  it("ranks formed guilds by their members' total levels", async () => {
    const owls = await guild("Iron Owls", "active", [
      [ada, "leader"],
      [bram, "member"],
    ]);
    await guild("Tin Larks", "active", [[cog, "leader"]]);
    await guild("Paper Wings", "charter", []);
    const view = await board(ada, "guilds");
    expect(view.rows).toEqual([
      expect.objectContaining({ rank: 1, id: owls, name: "Iron Owls", value: (await expectedTotal(ada)) + (await expectedTotal(bram)), detail: 2, you: true }),
      expect.objectContaining({ rank: 2, name: "Tin Larks", value: await expectedTotal(cog), detail: 1, you: false }),
    ]);
    expect((await board(cog, "guilds")).you.name).toBe("Tin Larks");
  });

  it("never shows a fully banned player, but still shows a chat-banned one", async () => {
    await db.query("UPDATE accounts SET ban = 'full', banned_at = now() WHERE login = 'lb-bram@example.com'");
    await db.query("UPDATE accounts SET ban = 'chat', banned_at = now() WHERE login = 'lb-cog@example.com'");
    for (const name of ["total", "cooking", "smithing", "net_worth"]) {
      const names = (await board(ada, name)).rows.map((row: { name: string }) => row.name);
      expect(names).not.toContain("Bram");
    }
    expect((await board(ada, "total")).rows.map((row: { name: string }) => row.name)).toEqual(["Ada", "Cog"]);
    const owls = (await board(ada, "guilds")).rows.find((row: { name: string }) => row.name === "Iron Owls");
    expect(owls).toMatchObject({ value: await expectedTotal(ada), detail: 1 });
  });

  it("refuses a board that does not exist, and a Tinker that does not", async () => {
    expect((await call("GET", `/tinkers/${ada}/leaderboards/story`)).status).toBe(400);
    expect((await call("GET", "/tinkers/999999/leaderboards/total")).status).toBe(404);
  });
});

// The leaderboards (GDD section 6, Leaderboards): total level, each of the
// sixteen skills, net worth, and guilds. There is no story board, by design.
// They open over the workshop from the side list or the phone's bar, so the
// first-session guide's order of places is left as it is.

import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { Pressable, ScrollView, Text, View } from "react-native";
import { api, type LeaderboardRow, type LeaderboardView } from "./api";
import { titleCase } from "./format";
import { colors, ui } from "./theme";

const Opener = createContext<{ available: boolean; open: () => void }>({ available: false, open: () => undefined });

/** How the navigation opens the boards; unavailable outside a workshop. */
export function useLeaderboards() {
  return useContext(Opener);
}

export function LeaderboardsProvider({ tinkerId, children }: { tinkerId: number; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const value = useMemo(() => ({ available: true, open: () => setOpen(true) }), []);
  return (
    <Opener.Provider value={value}>
      <View style={{ flex: 1 }}>
        {children}
        {open && (
          <View style={{ position: "absolute", top: 0, left: 0, right: 0, bottom: 0, zIndex: 10, backgroundColor: colors.soot }}>
            <Leaderboards tinkerId={tinkerId} onClose={() => setOpen(false)} />
          </View>
        )}
      </View>
    </Opener.Provider>
  );
}

const FIRST_BOARDS = ["total", "net_worth", "guilds"];

function boardName(board: string): string {
  if (board === "total") return "Total level";
  if (board === "net_worth") return "Net worth";
  if (board === "guilds") return "Guilds";
  return titleCase(board);
}

function noteOf(board: string): string {
  if (board === "total") return "Every skill's level added together. A tie goes to the Tinker with more XP.";
  if (board === "net_worth") return "Crowns held and Crowns in open buy orders, plus goods at the collectors' price. Gilded Cogs do not count.";
  if (board === "guilds") return "Formed guilds, by their members' total levels added together.";
  return "Ranked by XP in this skill.";
}

function valueText(board: string, row: LeaderboardRow): string {
  if (board === "net_worth") return `${row.value.toLocaleString()} Crowns`;
  if (board === "total" || board === "guilds") return `Total ${row.value.toLocaleString()}`;
  return `Level ${row.value}`;
}

function detailText(board: string, row: LeaderboardRow): string | null {
  if (row.detail === null) return null;
  if (board === "guilds") return row.detail === 1 ? "1 member" : `${row.detail} members`;
  return `${row.detail.toLocaleString()} XP`;
}

function Row({ board, row }: { board: string; row: LeaderboardRow }) {
  const detail = detailText(board, row);
  return (
    <View style={{ flexDirection: "row", alignItems: "baseline", gap: 10, paddingVertical: 5, borderBottomWidth: 1, borderBottomColor: colors.panelEdge }}>
      <Text style={[ui.number, { width: 40, textAlign: "right" }]}>{row.rank}</Text>
      <Text numberOfLines={1} style={[ui.text, { flex: 1, fontWeight: "700", color: row.you ? colors.brass : colors.ink }]}>
        {row.name}
        {row.you ? (board === "guilds" ? " (your guild)" : " (you)") : ""}
      </Text>
      <Text style={ui.number}>{valueText(board, row)}</Text>
      {detail !== null && <Text style={[ui.muted, { fontSize: 12, width: 120, textAlign: "right" }]}>{detail}</Text>}
    </View>
  );
}

export function Leaderboards({ tinkerId, onClose }: { tinkerId: number; onClose: () => void }) {
  const [board, setBoard] = useState("total");
  const [view, setView] = useState<LeaderboardView | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let live = true;
    api
      .leaderboard(tinkerId, board)
      .then((next) => {
        if (!live) return;
        setView(next);
        setError(null);
      })
      .catch((reason: Error) => live && setError(reason.message));
    return () => {
      live = false;
    };
  }, [tinkerId, board]);

  const boards = view?.boards ?? FIRST_BOARDS;
  const shown = view?.board === board ? view : null;
  const youBelow = shown?.you && !shown.rows.some((row) => row.you) ? shown.you : null;

  return (
    <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 16, alignItems: "center" }}>
      <View style={{ width: "100%", maxWidth: 720, gap: 12 }}>
        <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
          <Text style={[ui.heading, { fontSize: 22 }]}>Leaderboards</Text>
          <Pressable onPress={onClose} accessibilityRole="button" style={ui.button}>
            <Text style={ui.buttonText}>Back to the workshop</Text>
          </Pressable>
        </View>

        <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 6 }}>
          {boards.map((choice) => {
            const active = choice === board;
            return (
              <Pressable
                key={choice}
                onPress={() => setBoard(choice)}
                accessibilityRole="tab"
                accessibilityState={{ selected: active }}
                style={{
                  borderWidth: 1,
                  borderColor: active ? colors.brass : colors.panelEdge,
                  backgroundColor: active ? "rgba(201, 162, 90, 0.12)" : colors.panel,
                  borderRadius: 4,
                  paddingHorizontal: 8,
                  paddingVertical: 4,
                }}
              >
                <Text style={[ui.muted, { fontSize: 13, color: active ? colors.brass : colors.ink }]}>{boardName(choice)}</Text>
              </Pressable>
            );
          })}
        </View>

        <View style={[ui.panel, { gap: 6 }]}>
          <Text style={ui.heading}>{boardName(board)}</Text>
          <Text style={ui.muted}>{noteOf(board)} Each Tinker counts as of their last visit.</Text>
          {error && <Text style={[ui.muted, { color: colors.scald }]}>{error}</Text>}
          {!shown && !error && <Text style={ui.muted}>Tallying the boards…</Text>}
          {shown && shown.rows.length === 0 && (
            <Text style={ui.muted}>{board === "guilds" ? "No guild has formed yet." : "Nobody has trained this yet."}</Text>
          )}
          {shown?.rows.map((row) => <Row key={row.id} board={board} row={row} />)}
          {youBelow && (
            <>
              <Text style={[ui.muted, { textAlign: "center" }]}>…</Text>
              <Row board={board} row={youBelow} />
            </>
          )}
        </View>
      </View>
    </ScrollView>
  );
}

